    "meaning": {
      "prompt": "この本はあさって＿＿＿＿かえしてください。",
      "options": [
        "ばかり",
        "まで",
        "ばかりに",
        "までに"
      ],
      "answerIndex": 3
    },
    "optionExplanations": [
      "「ばかり」表示「淨是」，跟本句語意不符，錯誤。",
      "「まで」表示動作持續到某時間點，跟「歸還」這種瞬間動作的期限用法不符，錯誤。",
      "「ばかりに」表示「就因為…」的原因，跟本句語意不符，錯誤。",
      "「あさってまでに返してください」（請在後天之前歸還），「までに」標示期限，為正解。"
    ]
