    "optionExplanations": [
      "「にの」不是正確的日文助詞組合，錯誤。",
      "「アジアから留学生」直接接名詞不合文法，需要用「からの」連接後面的名詞，錯誤。",
      "「アジアからの留学生」（來自亞洲的留學生），「からの」是「から」加「の」變成連體修飾語的固定用法，為正解。",
      "「に」不能表示「來自」的意思，錯誤。"
    ]
