    "meaning": {
      "prompt": "おなかがいたいから半分＿＿＿＿食べます。",
      "options": [
        "だけ",
        "しか",
        "も",
        "と"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "「半分だけ食べます」（只吃一半），「だけ」表示限定「只」，為正解。",
      "「しか」要搭配後面的否定形（〜しか食べません），但本句是肯定形「食べます」，文法不符，錯誤。",
      "「も」表示強調數量之多，跟「只吃一半」的語意相反，錯誤。",
      "「と」跟本句語意不符，錯誤。"
    ]
